#!/usr/bin/env node
/** Build _hand363-b1-en.mjs + batchB from translation sources for audit failures */
import fs from "fs";
import path from "path";
import { fileURLToPath, pathToFileURL } from "url";
import { spawnSync } from "child_process";

const dir = path.dirname(fileURLToPath(import.meta.url));
const OC = path.join(dir, "..");

function esc(s) {
  return s.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
}

// Load translation maps
const { T: csT } = await import(pathToFileURL(path.join(dir, "_build363-translations.mjs")).href + "?v=" + Date.now());
const { T3 } = await import(pathToFileURL(path.join(dir, "_363-translations-data-part3.mjs")).href + "?v=" + Date.now());
const beer = JSON.parse(fs.readFileSync(path.join(dir, "_363-beer-hagolah-en.json"), "utf8"));

const allT = { ...beer, ...csT, ...T3 };
for (const f of fs.readdirSync(path.join(dir, "_en363-slugs")).filter((x) => x.endsWith(".json"))) {
  const slug = f.replace(".json", "");
  const tr = JSON.parse(fs.readFileSync(path.join(dir, "_en363-slugs", f), "utf8"));
  for (const [k, v] of Object.entries(tr)) allT[`${slug}:${k}`] = v;
}

// Manual overrides for 47 audit failures (key -> en)
const MANUAL = {
  "beur-hagra:7:_": `Lechi even. Chapter 2, and what is said lechi but, etc. — meaning but lechi even crushes, etc., even fragments and fragments of fragments. Hagahot Maimoniyot:`,
  "eliyah-rabbah:15:_": `[15] And equal from inside, etc. But in Tosafos daf 9 and the Rosh they compelled that in such a case it is not a lechi, for it is not called visible from outside except to those standing behind the mavo; but in truth Beit Yosef does not explain thus for Tosafos and the Rosh; nevertheless Chokhmat Shlomo explained thus and so it appears (Levush Yom Tov):`,
  "kaf-hachayyim:1:_": `(1) [Seif 1] A place that has three partitions, etc. The Tur wrote that from the Torah it is true reshut ha-yachid, and Beit Yosef wrote on this that he does not speak to make one who throws from reshus ha-rabbim into it liable, but to permit carrying in all of it, for such is the law of karmelit from the Torah, per Rambam chapters 14 and 17; but there are those who disagree and say that a place with three partitions is true reshut ha-yachid to make one who throws from reshus ha-rabbim into it liable; and the Maggid Mishneh already explained in chapter 17 that their dispute depends on the sugya in Eruvin — see there. But the Bach wrote that the Tur's view is not like the Rambam but to make liable also one who throws from reshus ha-rabbim into it — see there; and so the Taz s.k. 1, except he wrote to distinguish when open to reshus ha-rabbim and the public pushes into it — he is not liable for throwing into it from reshus ha-rabbim; but if the public does not push into it, it is true reshut ha-yachid — see there; and Eliyah Rabbah brought one opinion and wrote that from Bach and Magen Avraham it implies that in every case he is liable; and so Chayei Adam opinion 1; and so Nahar Shalom; and on the essence of this law — Rashi's view in Eruvin 12b and Bach in several places, Raavad in hasagot, Rosh first chapter of Sukkah, Rashba in chiddushim and Avodat HaKodesh, and Ritva — with three partitions or two partitions and lechi it is true reshut ha-yachid from the Torah; and see above siman 345 opinion 5 and siman 366 opinion 3, examine well:`,
  "kaf-hachayyim:5:_": `(5) There. Until some correction is made, etc. Correction of tzurat hapetach helps since it comes to be true reshut ha-yachid, as Tosafos wrote Eruvin 6 side 1 s.v. Rav and there 22 side 1 s.v. and R' Yehuda, and in the Rosh first chapter of Sukkah siman 34; but correction of korah helps only rabbinically, as Tosafos wrote Eruvin chapter 6 side 1 s.v. korah; and see there Tosafos 5 side 2 s.v. its breach that they wrote we learned that it helps in thickness of lechi and korah, and in a courtyard pas four — see there in Hagahot Chavot Yair who wondered on this, and see there in Maharsha what is written on this; and see in the Rosh chapter 8 siman 7 and Ritva daf 86 that with korah four tefachim wide it is a partition from the Torah, and with less than four tefachim it is only rabbinically because of recognition. Chayei Adam opinion 1; and see above siman 362 opinion 88:`,
  "kaf-hachayyim:6:_": `(6) Lechi is because of partition d'oraisa and korah is because of recognition; and Eruvin 12 — a mavo they qualified with lechi — one who throws into it is liable; with korah — exempt. For Rambam it is explained with three partitions, and for other poskim with two partitions. And there is practical difference for disqualifying testimony or a mumar who desecrates Shabbat d'oraisa — he is a mumar for the entire Torah; however some say we have no reshus ha-rabbim — see siman 345 in Taz s.k. 6. Mishnat Zekenim opinion 1; and see in our words there seif 7; and further practical difference whether he desecrated Shabbat with d'oraisa prohibition or d'rabbanan for correction; and see siman 334:`,
  "kaf-hachayyim:14:_": `(14) There. One tefach from here and one tefach from here. So too Beit Yosef in the name of R' Yehonatan, except he wrote on this that not specifically a tefach, for a mashehu from here and a mashehu from here suffices. And Tosafot Yeshanim wrote opinion 4 that thus explicitly in the language of R' Yehonatan that Beit Yosef brought siman 372; and what was not written thus in Shulchan Aruch — it must be that he retracted and was stringent like Tosafos' view — see there; and so in Maggid Mishneh opinion 1 he challenged Beit Yosef and wrote that in nishyayir we require specifically a width of one tefach — see there; and so R' Zalman opinion 2; however in Rambam chapter 15 law 12 he wrote that in nishyayir also a mashehu from here and a mashehu from here suffices; and so in Ritva Eruvin daf 10 and in R' Chaim's explanation there; and so Levush; and Eliyah Rabbah brought it opinion 2 and wrote that everywhere in Avodat HaKodesh for Rashba daf 6 — it is fit to rely on Rashba's ruling — see there; and Chayei Adam general rule 71 opinion 3 and Nishmat Adam there opinion 1 wrote that l'chatchila one should be concerned and forbid until one tefach remains, and in a time of pressing need one may rely on the lenient view that in nishyayir a mashehu suffices — see there; and it appears thus one should rule for practical law:`,
  "kaf-hachayyim:19:_": `(19) There. Even if it is not in its own fullness, etc. — it implies he means that not only if it is in its fullness and more than ten must it be corrected with tzurat hapetach; but even if it is not in its fullness, since it is more than ten it requires correction with tzurat hapetach; and although according to Rambam tzurat hapetach does not help for a breach more than ten except if standing is greater than the breach, as written above siman 362 seif 10 — we already wrote there opinion 89 that for a gap of three tefachim even for Rambam it helps — see there:`,
  "kaf-hachayyim:30:_": `(30) There. Gloss. And even if a person tied there, etc. — and it deals when they did not inform that they placed it for the sake of lechi; if so certainly he will go away and not stand there all day, therefore we require tying — Magen Avraham s.k. 3; and it implies that if they informed, tying is not required; and it is strained — if so why this trouble, better that he inform us; and it appears more that notification does not help here, lest he forget and go and tilt himself in a manner that it not be ten high — siman 362 seif 5 deals according to the moment, for then we are not concerned for this. Tosafot Yeshanim opinion 7, and Eliyah Rabbah brought it opinion 3; however R' Zalman opinion 5 wrote that if they informed that they place it for the sake of lechi we are not concerned he will go away, except then they must place it from erev Shabbat, for behold lechi is judged as partition and it is forbidden to make a partition from a person on Shabbat except not with his knowledge, as written siman 362 seif 5, end of his words; and see there seif 3 and below seif 11:`,
  "machatzit-hashekel:4:א": `(s.k. 4) No, etc. If so one day weekday — meaning perforce in any case one day weekday; for if the first day is weekday and two are weekday — it deals there with that work in a case where they said Shabbat, since it was permitted it is permitted, such as a city surrounded by a wall, as stated below siman 365 seif 7; nevertheless it was not permitted except for that Shabbat since it was permitted at Shabbat entry; but not permitted on the coming Shabbat; if so here since a weekday interrupts between Yom Tov and Shabbat, it is like the coming Shabbat — we do not say since it was permitted it is permitted; but even if you say one weekday (but the truth is not so, for they are expert in fixing the month and the first day is primary and we do not do the second day except because of ancestral custom) — it is obvious we do not apply since it was permitted it is permitted, for it was never permitted since a weekday interrupted:`,
  "machatzit-hashekel:6:_": `(s.k. 6) Even, etc. stones, etc. — it is a lechi; and the Taz below s.k. 19 wished to validate such for tzurat hapetach — see there; and in Tosafot Shabbos he disagrees and wrote that even adjacent to each other within three — nevertheless it is called doorways that people do not make, as stated daf 11 side 1; and therefore for lechi such is valid; but where tzurat hapetach is required it does not help — see there; nevertheless even for lechi, perforce the width of the stones must be a tefach, as stated in seif 4 in the name of Tosafos and the Tur (and the reason for pasin of a courtyard if nishyayir from the wall — we require specifically a tefach, as stated seif 1), although lechi suffices with a mashehu, for there is not as much recognition in a wall as in a complete pas, end of his words; and the same here for smeared plaster that the Rama wrote one makes for the sake of lechi — meaning the law of actual lechi, and all the more suffices; nevertheless the Taz wrote that we require some thickness in that plaster, and wrote not like one teacher who erred to validate by marking with white earth called kreid — see there:`,
  "machatzit-hashekel:12:א": `(s.k. 12) The extending lechi. Avodat HaGolah wrote, etc. R' Yehuda wrote that this law stems from what is stated daf 9 — R' Yehuda: a mavo they paved with lechayim less less than four tefachim over four amot — meaning they placed lechayim four within the mavo over four amot and between one lechi and its fellow is not four tefachim — we come to the dispute of Rashbag and the Rabbis; for Rashbag who holds that for anything less than four tefachim we say lavud — if so these lechayim are considered as one and there is four amot in its length and it leaves the category of lechi and another lechi is required; but for the Rabbis who hold specifically less than three tefachim we say lavud — for them another lechi is not required; and from this the Avodat HaGolah infers for us who rule less than three tefachim lavud — if so less than three tefachim from one lechi to its fellow, another lechi is required; except R' Yehuda challenged him — for even for Rashbag why need another lechi, let it be permitted through visible from outside and equal from inside; and Rashi explained that the way of those who place lechi is to extend somewhat outward so it is seen inside and outside that it was fixed for lechi (Tosafos disagree and explain another way) and they answer — this is the version of the sugya of R' Yehuda, and R' Yehuda holds visible from outside and equal from inside is not judged as lechi; if so for us who rule visible from outside and equal from inside is judged as lechi — if so the Avodat HaGolah should be challenged why another lechi is required; and R' Yehuda concluded and it is possible the Avodat HaGolah's intent is where the outer lechi was not extended outward at all — except it appears to R' Yehuda to explain that if so the conclusion for practical law is as Magen Avraham; and know that although Shulchan Aruch wrote the extending lechi does not help — visible from outside and equal from inside — and a mavo they paved with lechayim helps visible from outside and equal from inside — the reason is specifically for the extending lechi where one placed the entire lechi at the end of the mavo wall, meaning outside the mavo — if so the entire lechi is visible from outside and equal from inside; Eliyah Rabbah to permit through visible from outside and equal from inside — for this lechi that is visible from outside and equal from inside leaves the category of lechi and has the law of a wall; if so in a mavo they paved with lechayim where all lechayim stand inside, only part of the outer lechi is extended outward — R' Yehuda's explanation is to permit through visible from outside and equal from inside of the outer lechi:`,
  "machatzit-hashekel:13:_": `(s.k. 13) With its end — for on the other side it is shorter than this, etc. So it appears to me to resolve Eliyah Rabbah's question — Eliyah Rabbah challenged: but we say daf 10 side 1 — Rav Huna: lechi extending with the side of the mavo less than four amot is judged as lechi and one uses with its inner end four amot — judged as mavo; and we infer from this between lechayim it is forbidden, meaning we say one does not use the mavo except from the inner end of the lechi onward; and since we rule below siman 365 seif 4 that it is permitted to use opposite the lechi — why does Shulchan Aruch write here and one uses only with its inner end; and he answered that it deals open to karmelit, for in such a case it is explained below that it is forbidden to use opposite the lechi, for we say found its kind and it awoke; otherwise Shulchan Aruch should have explained and not been terse; and further if so why does the Talmud say we infer between lechayim forbidden — perhaps Rav Huna also deals open to karmelit; perforce the Talmud's explanation is strained since Rav Huna stated his words generally — and how do we interpret Shulchan Aruch's terse words; therefore Tosafot Yeshanim's explanation — and this is Magen Avraham's explanation; and what Eliyah Rabbah questioned on Rashi in what challenges the Talmud's question that it brought in s.k. 12 — it challenges Rashbag why need another lechi, behold it is visible from outside and equal from inside; and Rashi explained that the way of placing lechi is to extend the lechi somewhat outward, etc., as above; and Tosafos challenged: behold it implies in the entire sugya that for the Rabbis one must permit until the outer end of the lechi — and how is it permitted, etc. — for how will you permit reshus ha-rabbim, for a standard mavo the length of its walls is equal, end of Tosafos' words; and it is explained as Magen Avraham's words; and one should not ask why Shulchan Aruch was terse since a standard mavo the length of both its walls is equal; if so he placed the lechi opposite the thickness of the wall — on the side opposite the lechi there is a mavo wall, and therefore it is forbidden to carry even for us opposite the lechi — as Tosafos' question above; and what Magen Avraham wrote that in the Gemara it deals when its other side is also long — this is because perforce it must be according to Tosafos there who hold a standard mavo both walls' length is equal, and they challenged from this on Rashi's explanation as above; perforce it must be said that Tosafos hold that the Talmud was explaining what Rav Huna said — lechi extending with the side of the mavo — meaning with the side opposite the lechi, that it deals where the wall opposite the lechi is longer than the other wall opposite it; and now that he placed the lechi on the side of the shorter wall, the shorter side's length is extended by the lechi with the long side of the mavo opposite it and they become equal; if so it is fine that we infer between lechayim forbidden — unlike Shulchan Aruch which added lechi extending, etc., that he placed its end opposite the thickness of the wall — it implies this explains what extending with the side of the mavo means, and the side of the mavo means that side on which the lechi stands at its end; if so it deals as a standard mavo where both walls are equal, and therefore forbidden opposite the lechi since it has no wall opposite it; or one may say a plain way for Tosafos there — that is how they explain why the Talmud says we infer between lechayim forbidden — for Tosafos hold perforce Rav Huna does not deal with a standard mavo where both walls are equal, for if so an obvious matter that one does not use except from its inner end — for it has no wall opposite it; if so Rav Huna need not say and one uses with its inner end; he should only have said it is judged as lechi; perforce it comes to teach even where the wall opposite it is longer, nevertheless one is not permitted except with its inner end — for it holds between lechayim forbidden; unlike Shulchan Aruch which deals presumably as a standard mavo where walls are equal, and nevertheless writes and one uses with its inner end, although the Talmud considered this an obvious matter; nevertheless in Shulchan Aruch for us it is weak and lacking, for all that was needed was to teach:`,
  "machatzit-hashekel:16:_": `(s.k. 16) Enough, etc. — it is nine amot, for each brick is half a brick which is three tefachim length and three tefachim width, and the brick that is its half is one tefach width and half and length three tefachim; thus brick length opposite korah length — eighteen bricks are nine amah; from each side of the korah half an amah remains which is three tefachim; and not precise that in any case something is lacking, for it is impossible that there not be slight space between brick and brick; and since on each side there is only less than three tefachim — even that bit of korah does not exist at all — it is fine, for we say lavud from two directions, as Magen Avraham wrote s.k. 17:`,
  "machatzit-hashekel:19:ב": `(s.k. 20) And it extends, etc. — meaning that it is, etc. He needed to write thus to exclude Bach's view who wrote on Shulchan Aruch's words: he understood that the concern is where part of it is below ten and not all above ten — and he permits it, meaning this is an obvious matter; therefore Magen Avraham explained he means below from where it begins, etc.; if so the korah's height is ten tefachim but it does not reach near the ground; and so Bach explained the Tur's words — see there; and he wrote it is not similar to a mat where the korah is not visible and they think the mavo is permitted through the mat; but when the korah is visible because of its size, it does not leave the category of korah so much — the Rosh:`,
  "machatzit-hashekel:21:א": `(s.k. 21) Valid, etc. throw — meaning even if high from the wall we say throw as if they were placed below near the wall; except here even if placed below — behold it is distant on every side from the wall, for the korah is short; except since it is not distant three tefachim we say lavud from two sides; and know what Shulchan Aruch wrote and its bend inclines into the mavo — meaning not toward outside but toward the mavo wall width:`,
  "machatzit-hashekel:23:א": `(s.k. 23) Rather, etc. — and Rambam, etc. — its law is like a courtyard, meaning it is explained there that a pas four tefachim wide on one side or two pasin of mashehuyin suffice, as above seif 2:`,
  "machatzit-hashekel:24:_": `(s.k. 24) In a structure, etc. — and the same for earth, etc. — because R' Yehuda brought in the name of R' Yitzchak Ra'avan who inferred from the Rif's language that wrote he reduces it with a korah one tefach — it requires specifically something permanent and not earth lest it diminish in width or height without one's knowledge; and it was thought Bach's view in Shulchan Aruch is also thus that specifically something permanent; however R' Yehuda in his long work disagrees with R' Yitzchak Ra'avan and holds Rif's view is also like all poskim that earth also suffices, except one must beware it not diminish:`,
  "machatzit-hashekel:27:ג": `(ג) Law of courtyard — meaning the law of a mavo does not have even if houses and courtyards are open into it — nevertheless behold it is enclosed with four partitions on four sides, only that correction is required to divide between the place where Jews dwell and where gentiles dwell, for otherwise the gentiles who have no share in the eruv forbid the Jews to carry:`,
  "machatzit-hashekel:27:ט": `(ט) And it is obvious it deals, etc. — he comes to exclude the view of Mishna Berurah that he brought afterward who understood Mahariv's intent to be lenient in our mavo'ot — tzurat hapetach is not required in its crookedness since our mavo'ot are not pass-through to reshus ha-rabbim, for we have no reshus ha-rabbim nowadays; and therefore Mishna Berurah challenged in that responsum — this law depends on the dispute whether there is reshus ha-rabbim nowadays since the width is sixteen amah or we require specifically sixty myriads passing in it, as above siman 345 seif 7, and see Magen Avraham s.k. 7; and he brought Mishna Berurah's words and also Shulchan Aruch Mechaber already agreed above siman 345 with poskim that we have no reshus ha-rabbim nowadays, for we require sixty myriads passing in it; if so there is no challenge of Mishna Berurah on Mahariv; nevertheless Mahariv's explanation is not as Mishna Berurah understood; and there is practical difference for law — what Mahariv wrote there deals pass-through to reshus ha-rabbim, meaning it has no partitions; unlike Mahariv who deals in most towns that are enclosed for dwelling, only gentiles forbid the Jews; if so the Jews' mavo'ot are pass-through to the gentiles' mavo which are enclosed by a wall — only their law is as pass-through to a courtyard not combined in an eruv, for he wrote it is only removal of residents, meaning gentile residents; and it cannot be it is not enclosed by a wall — perforce without it, even though there is no reshus ha-rabbim nowadays, at least it is karmelit:`,
  "machatzit-hashekel:27:כ": `(כ) And see there seif 3 that even in its crookedness, etc. — from this it is also proved Mahariv's explanation is not as Mishna Berurah wrote, for nowadays it is karmelit — nevertheless correction was required in its crookedness, for regarding a crooked mavo there is no difference between pass-through to reshus ha-rabbim or to karmelit; and how did Mahariv write that for this reason tzurat hapetach is not required in its crookedness since it is not pass-through to reshus ha-rabbim; and so Taz challenged below siman 364 on Mahariv — he also understood like Mishna Berurah; and why does Taz require for law correction in its crookedness also for us — see there; Eliyah Rabbah, etc. Mahariv's intent in what he wrote that it is not pass-through to reshus ha-rabbim — meaning the city is surrounded by a wall; if so in unwalled cities indeed correction is required in its crookedness also for us, for we have no reshus ha-rabbim; and so Mishna Berurah returns above — for us if it is not wider than ten amot, two pasin suffice:`,
  "machatzit-hashekel:28:א": `(s.k. 28) Two reeds, etc. — as written siman 631 seif 3, in a sukkah that has two walls opposite each other one makes a wall four tefachim wide and mashehu and places it three tefachim less than mashehu near the wall and we say lavud; and there is qualification of sukkah that is seven tefachim — nevertheless some say tzurat hapetach requires placing a reed from the pas on the other wall; behold dedicated reeds for tzurat hapetach are not required; however it is more fit to emend in Magen Avraham siman 631 seif 2 — from there is the question — see there; and it is possible it is different there in sukkah where it is stringent, etc., for from Torah law two suffice as they are, and a third wall suffices with one tefach:`,
  "machatzit-hashekel:31:ב": `(ב) Lest they carry from the mavo, etc. — although it is explained at the end of this siman — a mavo level inside and slope to reshus ha-rabbim, etc. — no correction is required; it is different there, for from the start when they permitted carrying in this mavo they forbade them to carry to the slope place, and every coming Shabbat they remember this; unlike the sea where by itself it was not fit to use when the sandbar would rise — they would think it was also permitted to carry to the sea even now, only the sea is not fit to carry with the mavo and it was impossible to carry; and now when the sandbar rises they would carry, for they would think it is permitted; and even if they told them at first it is forbidden to carry outside the mavo to the sea — they would forget this, for much time passes until the sandbar rises; and until the sandbar rises there was nothing to remind them; unlike below end of this siman where every Shabbat they are forbidden to carry to the slope place — they will not forget:`,
  "magen-avraham:11:ב": `As if they relied on it. Even though they did not rely on it explicitly (Avodat HaGolah) — it implies that if explicitly they did not rely on it, such as they did not carry on the previous Shabbat through this lechi — it is not a lechi; and so Rashba whom R' Yehuda brought:`,
  "magen-avraham:26:ו": `Law of courtyards. Since most towns are surrounded by a wall in Yeshiv and afterward were enclosed — one should say the law of a courtyard and must correct the mavo'ot (between Jews and gentiles) as the law of one who comes to divide one courtyard into three and four domains if there were small paths in the courtyard between house and house — tzurat hapetach or two pasin of mashehuyin are required, as stated in Hagahot Maimoniyot in the name of Maharam, end of his words Terumat HaDeshen; and if so if the mavo is not ten amot wide, two pasin of mashehuyin suffice; and so Mahariv in his laws siman 18; and thus in Hagahot Maimoniyot explaining Maharam — our mavo'ot require only two lechayim, for they are only removal of residents, and tzurat hapetach is not required; nevertheless it appears our mavo'ot are not in their law as pass-through to require tzurat hapetach in its crookedness like the law of a crooked mavo, for there it deals pass-through to reshus ha-rabbim, end of his words; and it is obvious it deals with walled enclosure, for he wrote it is only removal of residents; but in unwalled cities tzurat hapetach is required, as Rashi wrote siman 364 in openings to karmelit — see there seif 63 — even in its crookedness correction is required, for there is no difference between reshus ha-rabbim and karmelit; and so Beit Yosef there in the name of responsum of Ran; and so Mishna Berurah siman 92; except he moved Mahariv's words to another view — see there; requires study, for I did not see practice thus; therefore it appears to me that since Rama explicitly wrote all our mavo'ot have the law of courtyards — it implies even without a wall, since houses and courtyards are not open into it, they have courtyard law, and in a courtyard there is no difference between crooked and straight — only one correction at its head is required; nevertheless regarding this that mavo'ot have courtyard law upon them — if it has no wall, tzurat hapetach is required since it is close to reshus ha-rabbim, as Semak wrote; but that its crookedness is not close to reshus ha-rabbim — correction in the bend is not required, end of gloss; and see siman 364 that on the other side lechi suffices; and siman 361:`,
  "magen-avraham:29:ב": `The sea rises as a sandbar. For such is the way of the sea — it shortens and becomes ground the width of a parsah, and partitions are nullified and they also carry in mavo'ot as initially (Rashi); and in any case it implies that even though the sea shortens, nevertheless a slope remains ten deep and is a partition — only the concern is lest they carry from the mavo to the place where the sea dried, which is karmelit even enclosed by the sea partition since it was not enclosed for dwelling, as written siman 365 seif 3; but when the sea exists there is no concern, for the sea is not fit to carry with the mavo, end of his words; and if so according to him complete partitions are required on the sea side, and tzurat hapetach or lechi or korah do not help as Eimimar ruled in Sura in his responsum; and the Tur holds like Rashi's view; if so correction of the rest of the mavo suffices; and it implies from Rashi's, Rosh's, and Tur's words that in other rivers we are not concerned lest a sandbar rise; and so Tosafos 4, 24 — see there; and know that in any case we require that the river be adjacent literally to the head of the mavo; but if distant from the houses ten amot correction is required, for that place is breached; and so Tosafos 4, 24 s.v. let them make tzurat hapetach and s.v. let them make lechi — see there; Constantinople even though breached to the sea in several places more than ten — it is as closed (R' Yehuda the Castilian Orach Chayim 94; and so Shach 92); see siman 345 seif 66; and in Rivash siman 345 he wrote a mavo pass-through to karmelit requires tzurat hapetach; and that case where one side is sea — it was not pass-through at both ends since it had three partitions, only on two sides it was somewhat breached on one side to sea and one to garbage heap, and the sea bank was ten deep, etc., end of his words; but the implication of poskim is that even fully pass-through to sea is permitted; and see Rashi siman 364; if so in our rivers whose way is to dry greatly in summer — forbid, see siman 365 seif 63; and know that if they freeze in rainy season the partition is nullified and it is forbidden to carry:`,
  "netiv-chayim:6:_": `(Taz s.k. 12.) And even though the law of lavud. This wording is in Hagahot Maimoniyot according to R' Meir's explanation that the korot themselves touch and they themselves must be a width of a tefach; but according to the other view that holds even distant — still the question remains: zil hakah leika shiyura and zil hakah leika shiyura; rather thus is the explanation: the other view holds it must specifically receive a brick in its width, and Rambam holds even receiving a brick in its length:`,
  "peri-megadim:1:א": `(א) There is Taz, Maggid Mishneh chapter 17 of Hilchot Shabbat law 9 — see there; and see siman 345 in Magen Avraham 1 — dispute of Rambam and other poskim; however lechi is because of partition d'oraisa and korah because of recognition; and Eruvin 12 — a mavo they qualified with lechi — one who throws into it is liable; with korah — exempt. For Rambam it is explained with three partitions, and for other poskim with two partitions; and practical difference for disqualifying testimony or mumar who desecrates Shabbat d'oraisa — he is a mumar for the entire Torah; however some say we have no reshus ha-rabbim — see siman 345 in Taz 6:`,
  "peri-megadim:1:ב": `(ב) The common person writing on the law of lavud and tzurat hapetach — I have thoughts on the matter and I set them forth here with God's help; know that lavud according to Maggid Mishneh is so, and even two lavud above and below, and even in length we say lavud; and in explaining lavud — not what people say as closed is considered, per Maggid Mishneh — lechi distant from the wall less than three tefachim, Magen Avraham 5; rather even where we say all air is as closed, like pas four in seif 35 and three ropes, etc., siman 362 — behold there is height ten, Rashi Sukkah 4 side 2 s.v. less, etc., that they extend, etc.; and behold in lavud Maggid Mishneh — it is a complete partition for all its matters and the conditions of lavud in Yoreh De'ah 100 side 1 — Raavad wrote in hasagot that lavud cannot be used to be stringent — see there in Magen Avraham siman 372 letter 9 he expanded on this and brought s.v. Eruvin 10 — see there; and in siman 632 letter 5 he explained what the Tur wrote that we do not say lavud to be stringent — it is as adjacent; do not err to explain his words that lavud as adjacent — for we rule lavud as extending and as closed per Avodat HaKodesh here; rather to say lavud entirely to be stringent as closed; and in invalid s'chach we do not say except as closed, not as extending; but with valid s'chach and invalid s'chach between them air less than three tefachim — I have doubt whether lavud — do we also say as adjacent; and invalid or only as extending and closed, and we say as closed in valid — see there; and see Levush; and behold if we say lavud as actual substance — to say as if it is not — the inquirer in Sukkah 4 side 2 and below in Hilchot Sukkah 633 seif 10 carved up to ten less than three tefachim to the wall we say lavud; and Rashi explained the carving as if reaching the wall — behold lavud as actual; and one may say this is a dispute in the Tur there — Magen Avraham there letter 8 — whether valid from carving and to the wall suffices; and see Beit Shmuel 2:`,
  "peri-megadim:1:ג": `(ג) Tzurat hapetach — its law is explained siman 362 seif 10 and here seif 26; and it implies even if made from asherah wood it is valid, for it does not require measure like lechi; and what requires receiving — d'oraisa straw and ashes do not apply; nevertheless it is permitted; see Tosafot Yeshanim letter 9 who brought s.v. ladder of asherah; and requires study; see Tosafot Yeshanim here letter 9 whether tzurat hapetach requires width four tefachim; and see there letter 19; and know I am uncertain whether tzurat hapetach is partition d'oraisa to make one who throws inside liable when one placed four pegs and tzurat hapetach above them — then tzurat hapetach helps to permit karmelit and breach more than ten, for it is a partition — therefore tzurat hapetach helps; and see siman 631 seif 2 and 3 — it implies tzurat hapetach alone does not help for sukkah; and in seif 6 one placed four pegs — it implies even if a reed was placed above them it does not help; and Magen Avraham letter 9 — every Maggid Mishneh is partition in sukkah helps, etc. — it implies tzurat hapetach does not help except for karmelit and the like to be true reshut ha-yachid through tzurat hapetach — requires much study; siman 356 regarding water — they do not make an opening — one may say tzurat hapetach does not help there where width is more than three tefachim; and siman 361 in Magen Avraham 4; and see Tosafot Yeshanim here letter 19 whether tzurat hapetach requires width four tefachim or even less; and requires study further:`,
  "peri-megadim:5:_": `From wood. Taz — all that stands to be scattered is considered scattered; rather explanation 1: the essence — for the Mechaber in siman 362 without it all the more so; and a finger-width is not needed — simply; and height ten tefachim — there is no question; see Be'er HaGolah letter 70; and see Tosafot Shabbos letter 13 who brought Tosafos Eruvin chapter 2 s.v. aval — see there; and behold it implies every matter where Maggid Mishneh requires measure — when crushed its measure is diminished, like shofar and lulav in length; although in width there is no measure, invalid; and one may say that for rabbinic matters measure is required in length alone like height ten — they were not stringent; and korah being rabbinic requires one tefach width — even in rabbinic matters it invalidates; and lulav with two in the mitzvah they were stringent — see there in Tosafot; however there is room to doubt in the matter — for Maggid Mishneh requires measure in height — if crushed is it invalid or only rabbinically; and practical difference — two partitions and lechi of asherah such as here; Magen Avraham 1; and Beit Shmuel 2; one may say Maggid Mishneh (1) and Tosafot Yeshanim here letter 13; and see Even HaEzer 124; Choshen Mishpat 1; and Beit Shmuel 2; one may say the Chavot Ya'ir's question how he wrote the get in Toldot — it implies entirely; one may say all that stands to burn is considered burned — only to be stringent and not to be lenient — see there; and siman 376 seif 3 and 439 seif 3; and mitzvot were not given for benefit — even in a rabbinic mitzvah; and such is considered a mitzvah although one carries rabbinic matters; unlike siman 362 seif 16 — ladder of asherah forbidden to ascend — see there; Magen Avraham letter 7; and requires study there:`,
  "peri-megadim:15:_": `It is not Taz; and Eliyah Rabbah 29 — wide korah four tefachim descends and closes when width is not more than ten; and also the eye rules over it — see there; and apparently printing error in what he wrote seven — only four — see there; nevertheless siman 361 in Magen Avraham 5 — wide four tefachim helps even above twenty; requires study. And lechi helps above twenty, for it is partition; and Bach seif 14 — lechi equal inside and outside is not judged as lechi unless something protrudes above somewhat higher than the mavo walls; and in such a case all that height above five amot has no recognition, although lechi is partition — nevertheless recognition is also required — see there; and Tosafot Yeshanim letter 53 brought it; and requires study letter 19:`,
  "peri-megadim:19:א": `Therefore Taz siman 362 in Taz 4 and Magen Avraham 19 — it implies one must beware in such a manner because of onlookers; and what is resolved in the Gemara Eruvin 11 side 2 regarding arch and what is written — see Tosafot Yeshanim letter 64 who challenged him from Eruvin 11 side 2 regarding arch and what is written that interruption does not ruin; and Yoreh De'ah 387 side 3 challenged him — see there; in Be'er HaGolah letter 2 for Maggid Mishneh an alternate approach in Eruvin and Yoma 11 side 2; what is the arch's height if not in a straight mezuzah nine — what arch and what lintel and what lintel has no height ten; and what the Gemara says in Eruvin and Yoma 11 side 2 where width is not four and one may carve four — extra teaches even without width four in the circle all that has carving four holds R' Meir one may carve; and for the Rabbis in every case all that has mezuzah height straight ten is obligated although there is no width four at all; and when there is not height ten straight, although there is width four in the circle itself — nevertheless which will you make mezuzah and which lintel; and one may say how did support say we need not touch tzurat hapetach to the reeds — for Maggid Mishneh and Rashi explained well from height ten, etc.; what is not so for Maggid Mishneh — the arch's height immediately becomes lintel; and requires study to reject and say the Rabbis do not hold thus; and in truth Rif and Rosh and halacha follows R' Nachman as taught according to him — it teaches us not like Maggid Mishneh's explanation; and in Maggid Mishneh Petach HaDevir 19 — halacha follows R' Nachman — he did not conclude as taught according to him; and with this one may say Taz's words — what requires a hole in the roof — understand; and one need not expand:`,
  "peri-megadim:20:_": `Lest Taz — in a city surrounded by a river, its banks ten high which is a partition, and they acquired from the lord as siman 382 not to forbid gentiles — he raised it is forbidden; and he brought Gemara Eruvin 8 side 1 — forbidden he did not say, for partitions stand; and he raised that even on other days of the year in summer it is forbidden to carry in the city — see there; behold the river — are they not surrounded by Hashem's presence in the city, and Hashem's Word; and Maggid Mishneh in any case even if there is slope place permitted, etc.; and Magen Avraham 41 in the name of Maggid Mishneh implies even if there is slope place forbidden — see there; and Taz holds even for Maggid Mishneh wherever there is slope place mound collected ten within four amot — permitted; and Magen Avraham in winter days forbids and in summer days possibly permits; and requires study there; nevertheless in other rivers for sandbar we are not concerned; and therefore he permitted where there is mound, etc.; Magen Avraham; and behold regarding sandbar concern — one may say the Rabbis do not disagree so much; unlike frozen water and the public passes there — it is actual reshus ha-rabbim — we should decree more; and see in siman 345 Taz 6 and Magen Avraham 7 — they are lenient to say nowadays it is karmelit; nevertheless here one may say; and behold one may say Rashi's explanation sandbar like width of parsah — they would carry there in the sea and it is enclosed not for dwelling as Magen Avraham wrote letter 41; and Eimimar who ruled in Sura in Uzla — one may say he holds properly we are not concerned for sandbar lest they carry from mavo to sandbar, for they were not accustomed to this and would not come to it; unlike within the city they would carry as initially — we properly concern; and Sura had no slope ten over four amot and properly concerned lest they carry in the city as initially and he ruled in Uzla; and in any case when there is slope it is permitted; and this that Taz brought Maggid Mishneh's and Rashi's explanation as parsah width — for special intent he brought thus as said; and requires study in Magen Avraham; and see responsum Knesset Yechezkel siman 2 and other simanim he expanded here — see there; and Magen Avraham 365 letter 9; and Eliyah Rabbah here letter 45; and regarding a city surrounded by a ditch ten deep and four wide — it is a complete partition to say regarding an city enclosed by a wall with doors and bar — therefore he permitted carrying in the city of Agh — see responsum Chacham Tzvi siman 5 and 6; and see siman 372 in Magen Avraham 29 — whatever the ditch width is less than four tefachim easy to step across — it is not a partition for the city; and if there are wide bridges more than ten — tzurat hapetach is specifically required; and requires study in Magen Avraham and here one need not expand; and know a river surrounding or mound around the city is karpef more than beit se'ah not enclosed for dwelling — Magen Avraham letter 48 wrote — except one may say where there are bridges wider than ten amot the partition around the city is nullified and afterward when tzurat hapetach was made at the bridge place as siman 358 seif 2 — it is enclosed except for reason of ceiling; and therefore where the bridge is not ten amot wide — otherwise forbidden to carry in the city; and requires study in Magen Avraham:`,
  "peri-megadim:21:_": `Rather Taz Eruvin 8 side 2 — it implies even if one wishes to use only opposite the short — nevertheless one does not place the korah diagonally lest they err and use the long opposite the long; and also there is not so much recognition when placed diagonally; and further korah on the mavo walls we require, and in length not on the mavo walls — for it is forbidden to use there; and therefore Rava said one places only opposite the short and did not say one uses only opposite the short; and one should not ask the first answer in Tosafos s.v. for Rava why need the reason it is not recognition — let it be resolved there is no partitions; and Avodat HaKodesh brought Tosafot Yeshanim; and what Taz wrote — apparently within the mavo even diagonally is permitted — meaning when there is not more than ten in the diagonal; and I saw that more than ten — even for Rav Kahana forbidden; the same within the mavo for Rava (and the word "rather diagonally" must be emended — and the intent is precise amot and not more); and with this Rif's words are resolved — more than ten all agree, etc., practical difference within the mavo as said; and Beit Yosef; and Taz wrote — from Shulchan Aruch's and Tur's language it implies within the mavo even if more than ten in the diagonal — permitted to place the korah diagonally; if not it should first say within the mavo permitted diagonally and afterward write tzurat hapetach permitted opposite long and short; nevertheless they are not equal, for korah within the mavo like opening width more than ten amot certainly does not help even when mavo walls are equal; and tzurat hapetach helps only when more than ten in the diagonal — permitted within the mavo with korah; and see Tosafot Yeshanim; and two lechayim Bach wrote there is no doubt at all — certainly it only permits opposite the short when placed at the end of the mavo; not like Bach and Magen Avraham who wrote opposite the short is reshus ha-rabbim — meaning lechi is partition and behold three partitions on the long side and the breach on the fourth side not in fullness; and all the more open to karmelit such as here; nevertheless one may say even open to karmelit two lechayim diagonally do not help, for the lechi at the short side itself permits carrying in the mavo only opposite it straight; and the lechi at the long side neither helps nor hurts, for opposite it is only reshus ha-rabbim; if so it is only like any tree and what helps the lechi at the short side — it has no partnership with the one outside who permits opposite it alone by itself because of partition; one sees as if a partition spread straight opposite it; and the second has no relevance in this; unlike korah placed diagonally from this to that — partnership is visible to the eyes that it goes from this to that; unlike two lechayim — here one does not need its fellow outside and permits opposite it well alone by itself because of partition; one sees as if partition spread straight opposite it; and the second has no partition relevance here; and one should not say what is written below that two lechayim permit in the middle of the mavo — there they stand straight and each needs its fellow to divide domains and there specifically two are required as written below; unlike here diagonally; and even within the mavo where korah diagonal is permitted — if one made two pasin diagonally there is no partnership — only the one closer to outside alone permits opposite it and the second is unnecessary; all this appears clear and there is not even doubt for permission:`,
  "peri-megadim:23:_": `But Taz — one courtyard itself may divide with tzurat hapetach or two pasin per Bach and Magen Avraham; and see Eruvin 14 side 2 — half a mavo has half a mavo — obvious; and one may say lest it comes to teach that the outer ones do not forbid it when they did not make lechi at the head of the mavo, although they have right of way; and one may say it teaches more than two; and one may say let us say it has only half as initially — since two courtyards are required, etc.; and one may say:`,
  "peri-megadim:28:ב": `(ב) The poor man said I will inscribe here words and names mentioned in this siman with some explanation. Pasin, lechayim, tzurat hapetach, korah: (1) Five pasin — one pas of the courtyard in seif 2 four tefachim or two pasin mashehu from here and from here; and in nishyayir from the wall four — we require one tefach from here and from here. (2) One pas four amot wide in a mavo wider than twenty explained here — we require precisely four amot to be considered a mavo by itself; and then air of this side and that does not come and nullify it; and even standing greater than breach in width four does not nullify it. (3) Pas four amot standing in the mavo width — has not the law of lechi by itself; but if intended it is lechi; but standing along the mavo wall length — even if placed for lechi it is nullified from lechi law although recognizable as in seif 12 and 13 — see there. (4) Pas of ditches — although standing greater than breach, nevertheless since on each side one amah from here and one from there — fine it is partition; Maggid Mishneh beginning Making Pasin 17 side 2; and Maggid Mishneh chapter 17 and Ritva; and there is pas 5 in siman 365 — suffices with pas four such as here — see Magen Avraham 1 — see there. Three lechayim: (1) Lechi that permits a mavo fully breached in ten amot width — no measure for thickness, height ten, valid from asherah wood, and must not be distant from mavo wall three tefachim as explained seif 6 through 8. I said to inscribe what is written Sidra Vayishlach — see there "and he hid them under the terebinth" — and in the name of Rabbeinu Bachye gentiles have no law of burial except scattering specifically; and in Maggid Mishneh chapter 8 from gentiles how to destroy gentile worship — he crushes or burns and casts into the sea; and see Yoreh De'ah siman 146 seif 14; and end of Temurah that burnt offerings' ashes are permitted except asherah wood; difficult — for otherwise it is not burnt; one may say ashes of graves are buried — possibly rabbinically; for Maggid Mishneh here letter 85 it is from foundations of Torah; and Penei Yehoshua Pesachim — unlike asherah wood Maggid Mishneh "it shall cleave to your hand" — and one who benefits is lashed for benefiting; and see Even HaEzer laws of marriage sanctification. And Taz letter 5; and in Tosafot Eruvin chapter 2 s.v. aval — practical difference between explanations — reed above two reeds in tzurat hapetach — explanation 1 permitted and explanation 2 forbidden; and korah that said there crushed its measure — difficult somewhat for explanation 2; and what Ran wrote in the name of Baal HaMaor Rosh Hashanah 29 — rabbinic mitzvot we say mitzvot were given for benefit — difficult for lechi from asherah wood how permitted; Maggid Mishneh; or four partitions we require; nevertheless it is karmelit; and we rule even rabbinic not given for benefit as I wrote elsewhere. Two lechi: (4) in seif 4 — width four in the wall we require one tefach, for in the wall itself there is no recognition in mashehu. (3) Lechi standing by itself seif 11 — valid even planted tree even less than tefach; and siman 362 and 13. Tzurat hapetach — reed above asherah wood I explained above in invalid korah explained its law. And lechi partition and one who throws to mavo is liable; and korah recognition and one who throws to mavo is exempt; I had no time now to study properly — perhaps I will succeed in coming simanim to explain further:`,
  "rabbi-akiva-eiger:6:_": `And behold in the essence of the section of Dikah — one should study from where; in such a case where there was another lechi and it fell on Shabbat — it does not help, lest we say they did not rely — only they did not know from yesterday about this lechi, or they did not carry on the previous Shabbat through this lechi, as Magen Avraham wrote s.k. 9; but in such a case where there was another lechi there — one may say since we rule on Shabbat once permitted always permitted — only when lechi fell, since there is no partition, we do not say once permitted always permitted; if so lest since this lechi is a partition — only recognition is lacking — one may say it is called they brought it for partition and we say once permitted always permitted; and from that in Eruvin 15 side 1 — Rav sat in that mavo — they showed him and he stood in his place — there is no proof; for Rav according to his view that even when partitions exist we do not say once permitted always permitted; and conversely here according to R' Huna who does not hold as Mar — that when partitions exist we say once permitted always permitted — there is to rely on the palm tree; and perhaps since the baraita also teaches its korot fell — we rule korah is because of recognition; if so when korah fell it is called partitions exist, for only recognition is lacking; perforce in any case since the Sages said with three partitions we permit only when they have recognition beforehand — where recognition was removed — it is as partitions were nullified; likewise this lechi without recognition — partition is nullified from it rabbinically; and still requires study:`,
  "rabbi-akiva-eiger:8:_": `There from asherah wood invalid. And if with korah four tefachim wide — it depends on two answers in Tosafos Eruvin chapter 6 in the reason lechi is valid from asherah wood — explanation 1: since its width is mashehu they were not stringent; see Magen Avraham s.k. 7; if so here with korah even four wide does not help from asherah wood; but for explanation of R' Avraham — lechi if plaster is smeared it is lechi; see Taz s.k. 5 — meaning korah cannot be through adhesion of crushed material, for it must be fit to receive a brick; if so with korah four wide it helps from asherah wood, for although crushed it is as if crushed material adhered and makes four — so it appears to me:`,
  "shaarei-teshuvah:12:_": `And with this Ba'er Heitev; and see in Emunat Shmuel siman 40 — if the ditch was blocked with earth and stones — if the blockage is not more than ten amot high it is like an opening and does not forbid; but if more than ten amot high it is like a breach; and see in responsum Chacham Tzvi siman 5 that the law of a city surrounded by a ditch ten deep and four wide is like a city enclosed by a high wall with doors and bar — therefore he permitted carrying in the city of Agh — see there; and so wrote also in responsum Ohel Yaakov siman 73 regarding permitting carrying in the city of Agh; however he wrote there are bridges over which people pass from side to side to karmelit — and he permitted in a manner that the bridges not be fixed with nails or building but movable and removable at any time when they need to raise them with chains — and it is like fit to remove; and through raising them the city would be locked and enclosed; and even if fixed nevertheless there is tzurat hapetach in the middle of the bridges; and since its breached head is to karmelit — tzurat hapetach suffices; and therefore through acquiring permission in the eruv and leaving a remainder not in the eruv for recognition — carrying is permitted; and see there that even if bridges not fixed are locked with a key — nevertheless fit to remove; and through raising the bridges and closing the key it is not fixed but temporary; and not similar to sunk in earth lacking action — see there; and see Noda B'Yehuda Mahadura Tinyana siman 42 who also wrote regarding a city breached entirely in the fourth direction only that a river runs along the city and city ground is ten tefachim higher than the water — only there is a bridge wider than ten — tzurat hapetach must be made on the bridge — see there; and see Knesset Yechezkel 62, 3, 4; and Shevut Yaakov 17; and Shevut Yaakov part 3 siman 28; wrote in Eben HaEzer or Rotterdam that water for them is a wall — permitted; and see in Even HaEzer and Mor U'Ketzia what is written regarding rivers whose way is to freeze on Taz's words; and see in Eshel Avraham what is written in the name of Knesset HaGedolah; and see there that if there is height ten from frozen water — permitted simply — see there:`,
};

// Merge manual into allT
Object.assign(allT, MANUAL);

// Get audit failures
const audit = spawnSync(process.execPath, [path.join(dir, "_audit-hand-slot9.mjs"), "363", "--list"], {
  cwd: OC,
  encoding: "utf8",
});
const lines = audit.stdout.split("\n");
const idx = lines.findIndex((l) => l.trim() === "[");
const needList = JSON.parse(lines.slice(idx).join("\n"));
const hand = JSON.parse(fs.readFileSync(path.join(dir, "work/hand-slot9-siman-363.json"), "utf8"));

const FIXES = {};
let found = 0;
let missing = [];
for (const n of needList) {
  const it = hand.items.find((x) => x.rel === n.rel && x.key === n.key);
  const fullKey = `${it.slug}:${it.key}`;
  const en = allT[fullKey];
  if (!en) {
    missing.push(fullKey);
    continue;
  }
  if (!FIXES[n.rel]) FIXES[n.rel] = {};
  FIXES[n.rel][n.key] = en;
  found++;
}

console.log("hand fixes:", found, "missing:", missing.length, missing.slice(0, 10));

// Write hand363-b1-en.mjs
const fixLines = ["/** worker-slot-9 — siman 363 hand batch 1 (" + found + " audit fixes) */", "export const FIXES = {"];
for (const [rel, m] of Object.entries(FIXES)) {
  fixLines.push(`  ${JSON.stringify(rel)}: {`);
  for (const [k, v] of Object.entries(m)) fixLines.push(`    ${JSON.stringify(k)}: \`${esc(v)}\`,`);
  fixLines.push("  },");
}
fixLines.push("};", "");
fs.writeFileSync(path.join(dir, "_hand363-b1-en.mjs"), fixLines.join("\n"), "utf8");

// Write batchB with beer-hagolah + slugs (not in batchA mech)
const SMALL = {};
for (const [k, v] of Object.entries(allT)) {
  if (k.startsWith("mechaber:")) continue;
  if (v?.trim()) SMALL[k] = v;
}
const bLines = [`/** OC siman 363 batch B — commentator blocks (${Object.keys(SMALL).length}) */`, "export const MECH = {};", "export const SMALL = {"];
for (const k of Object.keys(SMALL).sort((a, b) => a.localeCompare(b, "en"))) {
  bLines.push(`  ${JSON.stringify(k)}: \`${esc(SMALL[k])}\`,`);
}
bLines.push("};", "");
fs.writeFileSync(path.join(dir, "_siman363-batchB-data.mjs"), bLines.join("\n"), "utf8");
console.log("batchB:", Object.keys(SMALL).length, "keys");

if (missing.length) process.exit(1);
